input.query:
PREFIX schema: <https://schema.org/> PREFIX aw: <https://w3id.org/agentweb-testbed#>
SELECT ?name ?pn ?rate ?apr ?term ?type ?pts ?pay ?close ?loan WHERE {
?p a schema:MortgageLoan; schema:name ?pn; schema:provider ?pr; schema:interestRate ?rate; schema:annualPercentageRate ?apr; schema:loanTerm ?t; aw:rateType ?type; aw:estimatedMonthlyPayment ?m; aw:estimatedClosingCosts ?c; aw:exampleLoanAmount ?l.
?pr schema:name ?name. ?t schema:value ?term. ?m schema:value ?pay. ?c schema:value ?close. ?l schema:value ?loan.
OPTIONAL{?p aw:discountPoints ?pts}
FILTER(?term=30 && ?type="fixed" && ?rate<=7.5 && ?pay<=3600 && ?close<=14500)
} ORDER BY ?rate LIMIT 20

